/* Real Zotero reader, sliced files, persistent translations and library imports.
 * Use the PDF generated by test/build-parallel-fixture.py. */
E2E.run = async function () {
  const steps = E2E.result.steps;
  function check(name, ok) {
    steps.push({ name, ok: !!ok });
    if (!ok) throw Error(name);
  }
  const wait = async (test) => {
    for (let i = 0; i < 360; i++) {
      if (await test()) return;
      await new Promise((r) => setTimeout(r, 50));
    }
    throw Error("Timed out waiting for page selection");
  };
  await wait(() => Zotero.DeepRead?.Panes?.paneIDs?.chat);
  const D = Zotero.DeepRead;
  D.prefs.set("parser.provider", "mineru");
  D.prefs.set("cards.autoExplain", false);
  const libraryID = Zotero.Libraries.userLibraryID;
  const parent = new Zotero.Item("journalArticle");
  parent.libraryID = libraryID;
  parent.setField("title", "Range fixture");
  await parent.saveTx();
  const source = await Zotero.Attachments.importFromFile({
    file: Zotero.File.pathToFile(E2E.env("DEEPREAD_E2E_PDF")),
    parentItemID: parent.id
  });
  const reader = await Zotero.Reader.open(source.id);
  await reader._initPromise;
  const s = D.Session.forReader(reader);
  await s.init();
  const doc = s.overlay.readerDoc,
    scopes = { setTimeout, clearTimeout, Uint8Array, ArrayBuffer };
  Services.scriptloader.loadSubScript("chrome://deepread/content/lib/pdf-lib/pdf-lib.min.js", scopes);
  const { PDFDocument, PDFDict, PDFName } = scopes.PDFLib;
  const readPDF = async (path) => PDFDocument.load(Uint8Array.from(await IOUtils.read(path)));
  const requests = [],
    parsed = [];
  const parse = D.Parser.parsePDF,
    complete = D.LLM.complete;
  D.Parser.parsePDF = async ({ filePath, pdfApp, signal }) => {
    const pdf = await readPDF(filePath),
      p = pdf.getPage(0),
      n = PDFName.of;
    const pageObjects = pdf.context
      .enumerateIndirectObjects()
      .filter(([, v]) => v instanceof PDFDict && v.get(n("Type")) === n("Page"));
    check(
      "only selected physical page and no linked page tree reach the parser",
      pdf.getPageCount() === 1 &&
        pageObjects.length === 1 &&
        !p.node.Annots() &&
        pdfApp.pdfDocument.numPages === 1 &&
        filePath !== (await source.getFilePathAsync())
    );
    const data = await pdfApp.pdfDocument.getPageData({ pageIndex: 0 });
    const i = p.getRotation().angle === 90 ? 1 : data.chars.length ? 0 : 2;
    parsed.push(i);
    const items =
      i === 0
        ? [
            { text: "Layout comparison", bbox: [65, 42, 325, 74], text_level: 1 },
            { text: "The estimate also depends on the", bbox: [68, 871, 393, 903] }
          ]
        : i === 1
          ? [{ text: "sampling interval used in the experiment.", bbox: [55, 60, 600, 99] }]
          : [{ text: "OCR on a scanned page.", bbox: [64, 210, 442, 241] }];
    return { contentList: items.map((o, id) => ({ ...o, id, page_idx: 0, type: "text" })) };
  };
  D.LLM.complete = async (args) => {
    requests.push(JSON.stringify(args.messages));
    const rows = JSON.parse(args.messages[0].content.split("\n").slice(1).join("\n"));
    return {
      content: JSON.stringify({
        translations: rows.map((row) => ({
          id: row.id,
          translation: row.source_text.includes("Layout")
            ? "版式对照"
            : row.source_text.includes("estimate")
              ? "估计还取决于"
              : row.source_text.includes("sampling")
                ? "实验所用的采样间隔。"
                : "扫描页正文。"
        }))
      })
    };
  };
  const event = () => new doc.defaultView.Event("change", { bubbles: true });
  const button = doc.querySelector(".dr-parallel-button");
  let c;
  function options() {
    c.exportControl.value = "options";
    c.exportControl.dispatchEvent(event());
    return c.optionsDialog;
  }
  function set(panel, name, value) {
    const input = panel.querySelector('[name="' + name + '"]');
    input.value = value;
    input.dispatchEvent(event());
  }
  try {
    button.click();
    await wait(() => s.comparison?.page?.units);
    c = s.comparison;
    await c.showPage(1);
    let panel = options();
    check(
      "open settings before any translation",
      panel?.open && requests.length === 0 && parsed.length === 0
    );
    set(panel, "scope", "range");
    set(panel, "range", "1,4");
    check(
      "out-of-bounds selection disables both actions",
      panel.querySelector('[name="save"]').disabled && panel.querySelector('[name="translate"]').disabled
    );
    set(panel, "range", "3,1,3");
    panel.querySelector('[name="translate"]').click();
    await wait(() => !panel.querySelector("fieldset").disabled);
    const fp = c.page.fingerprint,
      record = (i) => D.Store.comparisonData(s.key, fp, "page:" + i + ":zh");
    check(
      "non-contiguous pages are parsed and translated while the current page stays untouched",
      parsed.join(",") === "0,2" &&
        !!(await record(0)) &&
        !(await record(1)) &&
        !!(await record(2)) &&
        c.pageIndex === 1
    );
    check(
      "neighbouring unselected prose was never sent to the language model",
      requests.length > 0 &&
        requests.every((body) => !body.includes("sampling interval") && !body.includes("Errors are"))
    );
    const requestCount = requests.length;
    panel.querySelector('[name="translate"]').click();
    await wait(() => !panel.querySelector("fieldset").disabled);
    check(
      "repeating the selection reuses geometry and accepted translations",
      parsed.length === 2 && requests.length === requestCount
    );
    panel.querySelector('[name="close"]').click();
    await wait(() => !c.optionsDialog);
    c.close(false);
    button.click();
    await wait(() => s.comparison?.root && s.comparison.page?.units);
    await c.showPage(1);
    const selected = { indices: [0, 2], layout: "alternating", translationFirst: true };
    const dir = E2E.env("DEEPREAD_E2E_SHOTS"),
      path = PathUtils.join(dir, "alternating.pdf");
    check(
      "selected cached pages export with an untranslated page on screen",
      (await c.savePDF("selection", path, selected)) && c.pageIndex === 1
    );
    const pdf = await readPDF(path),
      pages = pdf.getPages(),
      firstOriginal = pages[1];
    check(
      "alternating selection contains two pairs and retains original-size pages",
      pages.length === 4 && pages.every((p) => p.getWidth() === 612 && p.getHeight() === 792)
    );
    const annot = (firstOriginal.node.Annots()?.asArray() || []).map((ref) => pdf.context.lookup(ref));
    check(
      "links to excluded pages are omitted while an external source link survives",
      !annot.some((a) => a.has(PDFName.of("Dest"))) &&
        annot.some((a) => a.lookup(PDFName.of("A"))?.get(PDFName.of("S")) === PDFName.of("URI"))
    );
    const item = await c.savePDF("selection", null, { ...selected, destination: "library" });
    check(
      "export is stored as a PDF attachment on the source paper",
      item?.parentItemID === source.parentItemID && item.id !== source.id && (await item.fileExists())
    );
    const originalOpen = Zotero.Reader.open;
    let opened;
    Zotero.Reader.open = async function (id, ...args) {
      opened = id;
      return originalOpen.call(this, id, ...args);
    };
    try {
      panel = options();
      set(panel, "scope", "range");
      set(panel, "range", "1,3");
      set(panel, "layout", "alternating");
      set(panel, "order", "translated");
      set(panel, "destination", "library");
      panel.querySelector('[name="save"]').click();
      await wait(() => opened || !panel.querySelector("fieldset").disabled);
      check(
        "library action reopens the saved attachment and repeated exports keep its notes",
        opened === item.id && parent.getAttachments().length === 2 && requests.length === requestCount
      );
    } finally {
      Zotero.Reader.open = originalOpen;
    }
    const collection = new Zotero.Collection();
    collection.name = "Papers";
    await collection.saveTx();
    const standalone = await Zotero.Attachments.importFromFile({
      file: Zotero.File.pathToFile(path),
      libraryID,
      collections: [collection.id]
    });
    const other = await D.ParallelExport.attach(
      { session: { item: standalone, key: D.util.attachmentKey(standalone) } },
      path,
      { name: "selected", title: "Selected pages" },
      fp,
      ["standalone"]
    );
    check(
      "standalone PDFs keep their library and collections",
      other.libraryID === libraryID && !other.parentItemID && other.getCollections().includes(collection.id)
    );
    await c.showPage(0);
    const cached = await record(0), otherPage = await record(2);
    const previousData = s.data, contentList = c.page.partial.items;
    const paragraph = contentList.find(item => item.text.includes("estimate"));
    const inherited = "精读旧译文";
    s.data = { language: "zh", contentList, hierarchicalData: [{ pageIndex: 0, paragraphs: [{
      pageIndex: 0, paragraphIndex: 1, minerUid: paragraph.id, bbox: paragraph.bbox,
      paragraphText: paragraph.text, paragraphType: "text",
      translationLayout: { units: [{ sourceText: paragraph.text, translation: inherited }] }
    }] }] };
    c.prepareUnits(c.page);
    check("the paper can normally reuse a previous deep-read translation", c.page.units.some(u => u.translation === inherited));
    await D.Store.saveComparisonData(s.key, fp, "terms:v1:zh", [{ source: "estimate", target: "旧术语" }]);
    const intercepted=D.LLM.complete;
    try {
      c.retranslateButton.click();
      panel = c.optionsDialog;
      const translate = panel.querySelector('[name="translate"]');
      check("the toolbar opens a dedicated retranslation dialog with page, range and paper scope",
        panel.open && panel.querySelector('[name="save"]').hidden &&
          [...panel.querySelector('[name="scope"]').options].map(o => o.value).join() === "current,range,all");
      const sent = [];
      const rowsOf = args => JSON.parse(args.messages[0].content.split("\n").slice(1).join("\n"));
      D.LLM.complete = async args => {
        const rows = rowsOf(args);
        if (!sent.length) {
          const blank = await record(0);
          check("retranslation clears the selected cache and removes old text before requesting the model",
            !!blank.generation && blank.translations.length === 0 &&
              c.page.units.every(u => !u.translation || u.verbatim));
        }
        sent.push(...rows.map(row => row.source_text));
        return { content: JSON.stringify({ translations: rows
          .filter(row => row.source_text.includes("Layout comparison"))
          .map(row => ({ id: row.id, translation: "本轮新版标题" })) }) };
      };
      translate.click();
      await wait(()=>!panel.querySelector("fieldset").disabled);
      const partial = await record(0);
      check("fresh requests cover both old translations and only save the passages accepted in this run",
        sent.some(s => s.includes("Layout comparison")) && sent.some(s => s.includes("estimate")) &&
          partial.translations.length === 1 && partial.translations[0].text === "本轮新版标题" &&
          c.page.units.some(u => !u.translation) && !c.translateButton.hidden &&
          !(await D.Store.comparisonData(s.key, fp, "terms:v1:zh")));
      check("a previous run cannot add cached translations to a restarted page",
        !(await D.Store.mergeComparisonTranslations(s.key, fp, "page:0:zh", cached, cached)) &&
          JSON.stringify(await record(0)) === JSON.stringify(partial));
      panel.querySelector('[name="close"]').click();
      await wait(() => !c.optionsDialog);
      c.close(false);
      button.click();
      await wait(() => c.root && c.page?.units);
      await c.showPage(0);
      check("opening the reader again shows only the new title and a pending body passage",
        c.page.units.some(u => u.translation === "本轮新版标题") &&
          c.page.units.some(u => u.source.includes("estimate") && !u.translation));
      const resumed = [];
      D.LLM.complete = async args => {
        const rows = rowsOf(args);
        resumed.push(...rows.map(row => row.source_text));
        return { content: JSON.stringify({ translations: rows.map(row => ({ id: row.id, translation: "本轮续译正文。" })) }) };
      };
      c.translateButton.click();
      await wait(() => !c.page.busy);
      const finished = await record(0);
      check("continuing uses only the new run, reuses parsing and preserves pages outside the selection",
        resumed.length > 0 && resumed.every(s => !s.includes("Layout comparison")) &&
          finished.generation === partial.generation && finished.translations.some(row => row.text === "本轮续译正文。") &&
          parsed.length === 2 && !(await record(1)) && JSON.stringify(await record(2)) === JSON.stringify(otherPage));
    } finally {
      D.LLM.complete = intercepted;
      s.data = previousData;
      if (c.optionsDialog) c.optionsDialog.close();
    }
    // A result for pages 2–3 becomes available after the reader has reopened.
    // Retry page 3 through the actual parser, cache and local page-index map.
    D.Parser.parsePDF = parse;
    const hooks = ["_mineruRequestUpload", "_mineruPut", "_mineruPoll", "_download", "_extractZip"];
    const real = Object.fromEntries(hooks.map((key) => [key, D.Parser[key]]));
    let uploads = 0,
      available = false;
    try {
      D.Parser._mineruRequestUpload = async () => ({
        batchID: "existing-job-" + ++uploads,
        uploadURL: "test"
      });
      D.Parser._mineruPut = async () => {};
      D.Parser._mineruPoll = async () => ({ full_zip_url: "test" });
      D.Parser._download = async () => {
        if (!available) throw new Error("Result download unavailable");
        return [];
      };
      D.Parser._extractZip = async (bytes, dir) =>
        IOUtils.writeUTF8(
          PathUtils.join(dir, "content_list.json"),
          JSON.stringify([
            { page_idx: 0, type: "text", text: "Result for physical page two.", bbox: [50, 80, 450, 110] },
            { page_idx: 1, type: "text", text: "Result for physical page three.", bbox: [55, 88, 465, 120] }
          ])
        );
      const signal = c.controller.signal,
        initial = new Map();
      await D.RangeParser.fill(c, c.page, [1, 2], initial, signal);
      const persisted = await D.RangeParser.load(s.key, fp, "mineru");
      check(
        "download failure retains readable text and the original batch coordinates",
        !!persisted.get(1).fallback &&
          persisted.get(2).downloadJob.first === 1 &&
          persisted.get(2).downloadJob.count === 2
      );
      available = true;
      await D.RangeParser.fill(c, c.page, [2], persisted, signal, true);
      check(
        "reopening a multi-page result for one page preserves its number and uses one upload",
        uploads === 1 &&
          !persisted.get(2).fallback &&
          persisted.get(1).fallback &&
          persisted.get(2).items[0].page_idx === 2 &&
          persisted.get(2).items[0].text === "Result for physical page three."
      );
      available = false;
      const scan = new Map();
      let failed = false;
      try {
        await D.RangeParser.fill(c, c.page, [2], scan, signal);
      } catch {
        failed = true;
      }
      check("a scan with an unavailable result remains pending", failed && !scan.has(2));
      available = true;
      await D.RangeParser.fill(c, c.page, [2], scan, signal);
      check(
        "retrying a scan with no text layer fetches the previous job",
        uploads === 2 && scan.get(2)?.items.length === 1
      );
    } finally {
      Object.assign(D.Parser, real);
    }
    return { checks: steps.length, parserPages: parsed, modelCalls: requests.length };
  } finally {
    if (c?.root) c.close(false);
    D.Parser.parsePDF = parse;
    D.LLM.complete = complete;
  }
};
